class StripeTenantSettings(BaseSettings):
    api_key: SecretStr
    webhook_signing_secret: SecretStr
    currency: str = "usd"

@app.get("/api/v1/integrations/stripe/{merchant_id}")
async def get_merchant_stripe_settings(
    merchant_id: str,
    settings_resolver: SettingsResolver = Depends(get_settings_resolver),
    current_user: User = Depends(get_current_user)
):
    if current_user.merchant_id != merchant_id:
        raise HTTPException(status_code=403, detail="Forbidden: You do not own this merchant account")
    config_data = await settings_resolver.load_settings_for_merchant(merchant_id)
    if not config_data:
        raise HTTPException(status_code=404, detail="Integration not configured")
    stripe_settings = StripeTenantSettings(**config_data)
    return {
        "merchant_id": merchant_id,
        "currency": stripe_settings.currency,
        "webhook_secret": stripe_settings.webhook_signing_secret.get_secret_value()
    }
